import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.C4zpkcTP.js";const g=JSON.parse('{"title":"AI Agent Skill","description":"Laravel Money is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly.","frontmatter":{"title":"AI Agent Skill","description":"Laravel Money is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly."},"headers":[],"relativePath":"laravel-money/ai-agent-skill.md","filePath":"laravel-money/ai-agent-skill.md"}'),n={name:"laravel-money/ai-agent-skill.md"};function l(o,e,r,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-agent-skill" tabindex="-1">AI Agent Skill <a class="header-anchor" href="#ai-agent-skill" aria-label="Permalink to &quot;AI Agent Skill&quot;">​</a></h1><p>Laravel Money is built for humans and AI agents. These docs are written for developers, and the package also ships an agent skill: a short guide that teaches coding agents such as Claude Code, Codex and Cursor how to install, configure and use Laravel Money the way it&#39;s meant to be used.</p><h2 id="installing-the-skill" tabindex="-1">Installing the skill <a class="header-anchor" href="#installing-the-skill" aria-label="Permalink to &quot;Installing the skill&quot;">​</a></h2><p>If your app uses <a href="https://github.com/laravel/boost" target="_blank" rel="noreferrer">Laravel Boost</a>, the skill is installed for you by <code>php artisan boost:install</code>; run <code>php artisan boost:update</code> after updating Laravel Money to refresh it. With any other agent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-money</span></span></code></pre></div><p>Or copy <code>skills/laravel-money</code> from the <a href="https://github.com/laranex/laravel-money" target="_blank" rel="noreferrer">repository</a> into your project&#39;s <code>.claude/skills</code> or <code>.agents/skills</code> folder.</p><h2 id="what-the-skill-covers" tabindex="-1">What the skill covers <a class="header-anchor" href="#what-the-skill-covers" aria-label="Permalink to &quot;What the skill covers&quot;">​</a></h2><p>Work with money in a Laravel app using laranex/laravel-money: the immutable <code>Laranex\\LaravelMoney\\Money</code> value object, Eloquent casts, exact arithmetic, percentages, allocation, rounding and formatting with the correct precision for every currency.</p><p>It covers when to use the package, installing and configuring it, building money, calculating, formatting and serializing, storing amounts in the database, handling errors, testing your app and what to avoid. It is written from the package source and kept in the repository next to the code, so agents follow the same API, configuration and conventions these docs describe.</p><h2 id="keeping-it-current" tabindex="-1">Keeping it current <a class="header-anchor" href="#keeping-it-current" aria-label="Permalink to &quot;Keeping it current&quot;">​</a></h2><p>The skill lives in the package repository and is versioned with it, so it always describes the release you install. When you update Laravel Money, update the skill the same way you installed it.</p>',11)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
